import os
os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['OMP_NUM_THREADS']='1'
import numpy as np,mujoco,time,sys,multiprocessing as mp
from rcb_hb import Session
import cma
S=None

def init():
 global S,M,D,lo,hi,prefix,st,spec
 S=Session('balance_simple',instance='/app/instance.npz');M=S.model;D=S.data;lo=S.low.action_low;hi=S.low.action_high
 prefix=np.load('/app/output/mpc_cem_actions.npz')['actions'][:180]
 for a in prefix:S.step(a)
 spec=mujoco.mjtState.mjSTATE_INTEGRATION;st=np.empty(mujoco.mj_stateSize(M,spec));mujoco.mj_getState(M,D,st,spec)

def feat():
 R=D.xmat[12].reshape(3,3);B=D.xmat[23].reshape(3,3)
 # centered physical features around near balanced pose
 pitch=np.arctan2(R[0,2],R[2,2]);roll=np.arctan2(-R[1,2],R[2,2]);bp=np.arctan2(B[0,2],B[2,2]);br=np.arctan2(-B[1,2],B[2,2])
 xp,yp=D.subtree_com[1,:2];vx,vy=D.sensordata[2:4]
 f=np.r_[1., xp*10,vx*3,pitch*3,D.qvel[4],bp*3,D.qvel[29],D.qpos[26]*10,D.qvel[25]*3,
          yp*10,vy*3,roll*3,D.qvel[3],br*3,D.qvel[28],D.qpos[27]*10,D.qvel[26]*3,
          D.site_xpos[5,2]-2.,D.qvel[2]]
 return f

# fit independent output linear gains from mpc trajectory
init();allactions=np.load('/app/output/mpc_cem_actions.npz')['actions'];S.reset();X=[];Y=[]
for i,a in enumerate(allactions):
 if i>=100:
  X.append(feat());u=(a+1)/2*(hi-lo)+lo;Y.append([u[2],(u[3]+u[8])/2,u[4],(u[1]+u[6])/2,(u[3]-u[8])/2])
 S.step(a)
X=np.array(X);Y=np.array(Y);reg=np.eye(X.shape[1])*.05;reg[0,0]=.001
P=np.linalg.solve(X.T@X+reg,X.T@Y).T
np.savez('/app/output/fitted_controller.npz',P=P)

# do not fit again on import worker
scale=np.tile(np.r_[.05,np.full(18,.1)],5)
base=P.ravel()

def ctrl(p):
 z=p.reshape(5,19)@feat();q=np.zeros(19);q[[2,7]]=z[0];q[[3,8]]=z[1];q[[4,9]]=z[2];q[[1,6]]=z[3];q[3]+=z[4];q[8]-=z[4]
 R=D.xmat[12].reshape(3,3);yaw=np.arctan2(R[1,0],R[0,0]);q[[0,5]]=-.5*yaw-.2*D.qvel[5]
 return np.clip(q,lo,hi)

def rollout(x,record=False):
 p=base+scale*x;S.reset();mujoco.mj_setState(M,D,st,spec);mujoco.mj_forward(M,D);score=0;acts=[];metrics=[]
 for i in range(820):
  u=ctrl(p);a=np.clip(2*(u-lo)/(hi-lo)-1,-1,1).astype(np.float32);D.ctrl[:]=(a+1)/2*(hi-lo)+lo;mujoco.mj_step(M,D,nstep=10);mujoco.mj_rnePostConstraint(M,D)
  h=D.site_xpos[5,2];upr=D.xmat[12,8];v=np.linalg.norm(D.sensordata[2:4]);force=np.mean(D.actuator_force**2)
  g=np.exp(-2*v*v-8*(1-upr)-5*max(0,2.05-h)**2)*(.95+.05*np.exp(-force/1e4));score+=g
  if record:acts.append(a);metrics.append([h,upr,v,np.sqrt(force)])
  bad=D.qpos[2]<.8
  for j in range(D.ncon):
   pair=D.contact[j].geom
   if (0 in pair and 45 not in pair) or (45 in pair and 0 not in pair and 43 not in pair):bad=True;break
  if bad:break
 if record:return score+.1*(i+1),np.r_[prefix,np.array(acts)],np.array(metrics)
 return -score-.1*(i+1)

def work(x):return rollout(x)

def main():
 init();x=np.zeros(len(base));best=work(x);print('fit',-best,'P',P,flush=True)
