from rcb_hb import Session
s=Session('balance_simple',instance='/app/instance.npz');a=np.load('/app/output/mpc_cem_actions.npz')['actions'];s.reset()
for x in a[:200]:s.step(x)
m=s.model;d=s.data;spec=mujoco.mjtState.mjSTATE_INTEGRATION;st=np.empty(mujoco.mj_stateSize(m,spec));mujoco.mj_getState(m,d,st,spec)
q=[];v=[]
for x in a[200:210]:s.step(x);q.append(d.qpos.copy());v.append(d.qvel.copy())
for forward in [True,False]:
 mujoco.mj_setState(m,d,st,spec)
 if forward:mujoco.mj_forward(m,d)
 for i,x in enumerate(a[200:210]):
  x=np.clip(x,-1,1).astype(np.float32);d.ctrl[:]=s.low.task.unnormalize_action(x);mujoco.mj_step(m,d,nstep=10);mujoco.mj_rnePostConstraint(m,d)
  print(forward,i,'qerr',np.max(np.abs(q[i]-d.qpos)),'verr',np.max(np.abs(v[i]-d.qvel)))
